import { useCallback, useState } from 'react';
import { Button, Divider, Drawer, Menu, MenuItem } from '@jinx-ui/react';

export type SideNavKey = 'projects' | 'team' | 'settings' | 'logout';

interface SideNavProps {
  onNavigate: (key: SideNavKey) => void;
}

const navItems: ReadonlyArray<{ key: SideNavKey; label: string }> = [
  { key: 'projects', label: 'Проекты' },
  { key: 'team', label: 'Команда' },
  { key: 'settings', label: 'Настройки' },
];

export default function SideNav({ onNavigate }: SideNavProps) {
  const [open, setOpen] = useState(false);

  const select = useCallback(
    (key: SideNavKey) => {
      onNavigate(key);
      setOpen(false);
    },
    [onNavigate],
  );

  return (
    <>
      <Button
        variant="secondary"
        aria-haspopup="dialog"
        aria-expanded={open}
        onClick={() => setOpen(true)}
      >
        Меню
      </Button>

      <Drawer
        open={open}
        placement="left"
        title="Навигация"
        onClose={() => setOpen(false)}
      >
        <Menu
          aria-label="Основная навигация"
          style={{ paddingBlock: 'var(--jx-space-2)' }}
        >
          {navItems.map((item) => (
            <MenuItem key={item.key} onSelect={() => select(item.key)}>
              {item.label}
            </MenuItem>
          ))}

          <Divider style={{ marginBlock: 'var(--jx-space-2)' }} />

          <MenuItem tone="danger" onSelect={() => select('logout')}>
            Выйти
          </MenuItem>
        </Menu>
      </Drawer>
    </>
  );
}

